    WorkflowTask = apps.get_model("documents", "WorkflowTask")
    ManagementDirective = apps.get_model("documents", "ManagementDirective")

    for task in WorkflowTask.objects.using(alias).filter(status="PENDING").select_related("instance"):
        events = AuditEvent.objects.using(alias).filter(document_id=task.instance.document_id).order_by("occurred_at", "pk")
        event = next((candidate for candidate in events if candidate.context.get("task_id") == task.pk), None)
        if event is None:
            event = next((candidate for candidate in events if
                          candidate.action == "UNDER_REVIEW"
                          and candidate.context.get("workflow_id") == task.instance_id
                          and candidate.context.get("cycle") == task.cycle
                          and candidate.context.get("reviewer_id") == task.assigned_to_id), None)
        if event:
            Receipt.objects.using(alias).get_or_create(
                recipient_id=task.assigned_to_id, event_id=event.pk,
                defaults={"workflow_task_id": task.pk},
            )

    incoming_events = AuditEvent.objects.using(alias).filter(
        action="INCOMING_REGISTERED", document__document_type__code="IC",
        document__status="REGISTERED",
    ).order_by("document_id", "-occurred_at", "-pk")
    seen_documents = set()
    for event in incoming_events:
        if event.document_id in seen_documents:
            continue
        seen_documents.add(event.document_id)
        if ManagementDirective.objects.using(alias).filter(target_document_id=event.document_id).exists():
            continue
        manager_grant = next((grant for grant in event.context.get("visibility_grants", [])
                              if grant.get("reason") == "receiving_office_designated_head"
                              and grant.get("grant_created")), None)
        if not manager_grant:
            continue
        recipient_id = manager_grant.get("user_id")
        if recipient_id and recipient_id != event.actor_id:
            Receipt.objects.using(alias).get_or_create(recipient_id=recipient_id, event_id=event.pk)


